  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #weapon-name { font-size: 13px; letter-spacing: .1em; color: var(--muted); margin-top: 4px; }

  #money { position: fixed; right: 32px; bottom: 118px; text-align: right; font-family: var(--font-readout); font-size: 15px; color: var(--accent); }
