  #spike-bar { position: fixed; left: 50%; top: 96px; transform: translateX(-50%); width: 280px; text-align: center; }
  #spike-label { font-family: var(--font-readout); font-size: 12px; letter-spacing: .12em; color: var(--accent); margin-bottom: 5px; }
  #spike-track { height: 5px; background: var(--hairline); border-radius: 3px; overflow: hidden; }
