  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 34px; line-height: 1.1; font-weight: 600; letter-spacing: .06em; }
  .panel h1 .amber { color: var(--accent); }
  .panel p { margin: 0 0 24px; max-width: 48ch; font-size: 16px; line-height: 1.55; color: var(--muted); }
  .panel button { font: inherit; font-weight: 600; padding: 12px 18px; border: 1px solid var(--accent); border-radius: var(--radius-control); background: var(--accent); color: var(--canvas); cursor: pointer; }
  .panel button:hover { background: var(--ink); border-color: var(--ink); }
  .panel button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }

