  #buy-menu[hidden] { display: none; }
  #buy-menu .panel { width: min(560px, 100%); }
  #buy-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px; }
  #buy-head h2 { margin: 0; font-size: 24px; letter-spacing: .06em; }
  #buy-money { font-family: var(--font-readout); font-size: 22px; color: var(--accent); }
  #buy-sub { color: var(--muted); font-size: 14px; margin: 0 0 18px; }
  .buy-item { display: grid; grid-template-columns: 28px 1fr auto; gap: 4px 10px; padding: 10px 12px; border: 1px solid var(--hairline); border-radius: var(--radius-panel); margin-bottom: 8px; cursor: pointer; }
  .buy-item:hover { border-color: var(--accent); }
  .buy-item.cant { opacity: .45; }
  .buy-item.owned { border-color: var(--muted); }
  .buy-item.current { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 12%, transparent); }
  .buy-key { font-family: var(--font-readout); color: var(--accent); }
  .buy-name { font-weight: 600; }
  .buy-desc { grid-column: 2; color: var(--muted); font-size: 13px; }
  .buy-price { grid-row: 1; grid-column: 3; font-family: var(--font-readout); color: var(--accent); }
  #buy-close { margin-top: 8px; width: 100%; }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #damage { transition-duration: 0.01ms; }
  }
</style>
</head>
